# ============================================================
# CELL 1 — provenance, content addressing, resumable budget manager
# ============================================================
DIRS = {
    name: REPORT_ROOT / name
    for name in (
        "canonical", "models", "metrics", "utility", "tables", "figures",
        "manifests", "logs", "job_state", "cache", "package",
    )
}
for directory in DIRS.values():
    directory.mkdir(parents=True, exist_ok=True)

RUN_ID = os.environ.get("TIOT_RUN_ID", time.strftime("run_%Y%m%d_%H%M%S"))
EVENTS_PATH = DIRS["logs"] / "events.jsonl"
LEDGER_PATH = DIRS["job_state"] / "job_ledger.json"
COST_MODEL_PATH = DIRS["job_state"] / "cost_model.json"


def now_iso() -> str:
    return pd.Timestamp.now(tz="UTC").isoformat()


def elapsed_hours() -> float:
    return (time.time() - GLOBAL_START_TS) / 3600.0


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def sha256_file(path: str | Path, chunk_bytes: int = 8 * 1024 * 1024) -> str:
    h = hashlib.sha256()
    with Path(path).open("rb") as handle:
        for chunk in iter(lambda: handle.read(chunk_bytes), b""):
            h.update(chunk)
    return h.hexdigest()


def stable_hash(obj: Any) -> str:
    return sha256_bytes(json.dumps(obj, sort_keys=True, default=str).encode("utf-8"))


def callable_fingerprint(fn) -> str:
    """Stable code fingerprint used in cache keys even when the engine label is unchanged."""
    code = getattr(fn, "__code__", None)
    if code is None:
        return stable_hash(repr(fn))
    return sha256_bytes(
        code.co_code
        + repr(code.co_consts).encode("utf-8")
        + repr(code.co_names).encode("utf-8")
    )


def _unique_temp_path(path: str | Path) -> Path:
    """Return a same-directory unique temporary path for atomic replacement.

    A deterministic ``file.tmp`` name is unsafe when two resume attempts overlap or
    a previous process is interrupted mid-write.  Same-directory unique temporaries
    preserve atomic ``os.replace`` semantics without cross-process collisions.
    """
    path = Path(path)
    return path.with_name(
        f".{path.name}.{os.getpid()}.{time.time_ns()}.{random.randrange(1 << 30):08x}.tmp"
    )


def atomic_write_bytes(path: str | Path, payload: bytes) -> Path:
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = _unique_temp_path(path)
    try:
        with temp.open("wb") as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temp, path)
    finally:
        temp.unlink(missing_ok=True)
    return path


def atomic_write_text(path: str | Path, text: str, encoding: str = "utf-8") -> Path:
    return atomic_write_bytes(path, text.encode(encoding))


def write_json(path: str | Path, obj: Any) -> Path:
    payload = json.dumps(obj, indent=2, sort_keys=False, default=str)
    return atomic_write_text(path, payload)


def read_json(path: str | Path, default: Any = None) -> Any:
    path = Path(path)
    if not path.exists():
        return default
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return default


try:
    import pyarrow  # noqa: F401
    FRAME_EXT = ".parquet"
except Exception:
    FRAME_EXT = ".pkl"


def save_frame(df: pd.DataFrame, path: str | Path) -> Path:
    path = Path(path)
    if path.suffix == ".parquet" and FRAME_EXT == ".pkl":
        path = path.with_suffix(".pkl")
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = _unique_temp_path(path)
    try:
        if path.suffix == ".parquet":
            df.to_parquet(temp, index=False)
        else:
            df.to_pickle(temp)
        os.replace(temp, path)
    finally:
        temp.unlink(missing_ok=True)
    return path


def load_frame(path: str | Path) -> pd.DataFrame:
    path = Path(path)
    return pd.read_parquet(path) if path.suffix == ".parquet" else pd.read_pickle(path)


def log_event(event: str, **kwargs: Any) -> None:
    record = {
        "ts": now_iso(),
        "run_id": RUN_ID,
        "elapsed_h": round(elapsed_hours(), 6),
        "event": event,
        **kwargs,
    }
    with EVENTS_PATH.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(record, default=str) + "\n")
    payload = " " + json.dumps(kwargs, default=str) if kwargs else ""
    print(f"[{record['elapsed_h']:7.3f}h] {event}{payload}")


CACHE_STATS = {"hit": 0, "miss": 0, "seconds_saved": 0.0}


def cached(namespace: str):
    """Disk memoisation with an explicit scientific key."""
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, _key: dict[str, Any] | None = None, **kwargs):
            if _key is None:
                return fn(*args, **kwargs)
            cache_key = stable_hash({
                "namespace": namespace,
                "engine": CFG["engine_version"],
                "function": callable_fingerprint(fn),
                "key": _key,
            })
            path = DIRS["cache"] / namespace / f"{cache_key}.pkl"
            if path.exists():
                try:
                    payload = pickle.loads(path.read_bytes())
                    CACHE_STATS["hit"] += 1
                    CACHE_STATS["seconds_saved"] += float(payload.get("seconds", 0.0))
                    return payload["value"]
                except Exception:
                    path.unlink(missing_ok=True)
            started = time.time()
            value = fn(*args, **kwargs)
            path.parent.mkdir(parents=True, exist_ok=True)
            atomic_write_bytes(
                path,
                pickle.dumps({"value": value, "seconds": time.time() - started}),
            )
            CACHE_STATS["miss"] += 1
            return value
        return wrapper
    return decorator


def cache_report() -> dict[str, Any]:
    report = dict(CACHE_STATS)
    report["hours_saved"] = round(report["seconds_saved"] / 3600.0, 4)
    write_json(DIRS["manifests"] / "cache_report.json", report)
    return report


PACKAGE_VERSIONS = {
    name: package_version(name)
    for name in (
        "numpy", "pandas", "scipy", "scikit-learn", "matplotlib",
        "pyarrow", "joblib", "torch",
    )
}
NOTEBOOK_SHA256 = sha256_file(NOTEBOOK_PATH) if NOTEBOOK_PATH.exists() else None
ROOT_IDENTITY_PATH = REPORT_ROOT / "run_identity.json"
ROOT_IDENTITY = {
    "engine_version": CFG["engine_version"],
    "mode": MODE,
    "scientific_config_hash": stable_hash({
        key: value for key, value in CFG.items()
        if key not in {"ethics_status", "ethics_reference", "external_result_manifests"}
    }),
}
_existing_root_identity = read_json(ROOT_IDENTITY_PATH, None)
if (
    _existing_root_identity
    and _existing_root_identity != ROOT_IDENTITY
    and not env_flag("TIOT_ALLOW_REPORT_ROOT_REUSE", False)
):
    raise RuntimeError(
        "The report root contains artifacts from a different engine/mode/configuration. "
        "Use a fresh TIOT_REPORT_ROOT or explicitly set TIOT_ALLOW_REPORT_ROOT_REUSE=true "
        "only for a controlled migration."
    )
write_json(ROOT_IDENTITY_PATH, ROOT_IDENTITY)
write_json(DIRS["manifests"] / "effective_config.json", CFG)
write_json(DIRS["manifests"] / "environment.json", {
    "python": sys.version,
    "python_executable": sys.executable,
    "platform": platform.platform(),
    "packages": PACKAGE_VERSIONS,
    "detected_cpus": DETECTED_CPUS,
    "blas_threads": {
        key: os.environ.get(key)
        for key in ("OMP_NUM_THREADS", "OPENBLAS_NUM_THREADS", "MKL_NUM_THREADS")
    },
    "notebook_path": str(NOTEBOOK_PATH),
    "notebook_sha256": NOTEBOOK_SHA256,
    "run_id": RUN_ID,
})
write_json(DIRS["manifests"] / "ethics_and_governance.json", {
    "ethics_status": CFG["ethics_status"],
    "ethics_reference": CFG["ethics_reference"],
    "household_consent": "Document in manuscript/artifact package",
    "payload_retention": "Document in manuscript/artifact package",
    "identifier_pseudonymisation": "Document in manuscript/artifact package",
})


class ScientificInvalidFit(RuntimeError):
    """Expected model failure: execution completed, scientific result is unusable."""
    def __init__(self, message: str, diagnostics: dict[str, Any] | None = None):
        super().__init__(message)
        self.diagnostics = diagnostics or {}


COST_MODEL: dict[str, list[float]] = read_json(COST_MODEL_PATH, {}) or {}
JOB_LEDGER: dict[str, dict[str, Any]] = read_json(LEDGER_PATH, {}) or {}


def estimate_cost_seconds(kind: str, default: float = 600.0) -> float:
    observations = [float(x) for x in COST_MODEL.get(kind, []) if np.isfinite(x) and x > 0]
    if not observations:
        return default
    # Conservative upper estimate; avoids starting jobs that only fit under the mean.
    return float(max(np.quantile(observations, 0.80), np.mean(observations)))


def record_cost(kind: str, seconds: float) -> None:
    COST_MODEL.setdefault(kind, []).append(float(seconds))
    COST_MODEL[kind] = COST_MODEL[kind][-20:]
    write_json(COST_MODEL_PATH, COST_MODEL)


def hours_left(include_reserve: bool = True) -> float:
    reserve = RESERVE_HOURS if include_reserve else 0.0
    return MAX_WALLTIME_HOURS - elapsed_hours() - reserve


def can_afford(kind: str, safety_factor: float = 1.35) -> bool:
    return hours_left(include_reserve=True) * 3600.0 >= safety_factor * estimate_cost_seconds(kind)


def persist_ledger() -> None:
    write_json(LEDGER_PATH, JOB_LEDGER)


def ledger_entry_valid(job_id: str, context: dict[str, Any]) -> bool:
    entry = JOB_LEDGER.get(job_id)
    if not entry:
        return False
    if entry.get("execution_status") != "completed":
        return False
    if entry.get("context_hash") != stable_hash(context):
        return False
    result_path = entry.get("result_path")
    if result_path and not Path(result_path).exists():
        return False
    return True


def mark_job(
    job_id: str,
    execution_status: str,
    scientific_status: str,
    context: dict[str, Any],
    **extra: Any,
) -> None:
    JOB_LEDGER[job_id] = {
        "execution_status": execution_status,
        "scientific_status": scientific_status,
        "context_hash": stable_hash(context),
        "context": context,
        "ts": now_iso(),
        "elapsed_h": round(elapsed_hours(), 6),
        **extra,
    }
    persist_ledger()


def run_budgeted(
    job_id: str,
    cost_kind: str,
    context: dict[str, Any],
    fn,
    *args,
    **kwargs,
) -> dict[str, Any]:
    if ledger_entry_valid(job_id, context):
        entry = JOB_LEDGER[job_id]
        return {
            "job_id": job_id,
            "execution_status": "cached",
            "scientific_status": entry.get("scientific_status"),
            "result_path": entry.get("result_path"),
        }

    if not can_afford(cost_kind):
        mark_job(
            job_id,
            "deferred_budget",
            "not_evaluated",
            context,
            estimated_seconds=estimate_cost_seconds(cost_kind),
        )
        log_event("job_deferred_budget", job_id=job_id, cost_kind=cost_kind)
        return {
            "job_id": job_id,
            "execution_status": "deferred_budget",
            "scientific_status": "not_evaluated",
        }

    started = time.time()
    try:
        result = fn(*args, **kwargs)
        seconds = time.time() - started
        record_cost(cost_kind, seconds)
        scientific_status = str(result.get("scientific_status", "valid")) if isinstance(result, dict) else "valid"
        result_path = str(result.get("result_path")) if isinstance(result, dict) and result.get("result_path") else None
        mark_job(
            job_id,
            "completed",
            scientific_status,
            context,
            seconds=seconds,
            result_path=result_path,
        )
        log_event(
            "job_completed",
            job_id=job_id,
            scientific_status=scientific_status,
            seconds=round(seconds, 2),
        )
        return {
            "job_id": job_id,
            "execution_status": "completed",
            "scientific_status": scientific_status,
            "result_path": result_path,
        }
    except ScientificInvalidFit as exc:
        seconds = time.time() - started
        record_cost(cost_kind, seconds)
        mark_job(
            job_id,
            "completed",
            "invalid_fit",
            context,
            seconds=seconds,
            reason=str(exc),
            diagnostics=exc.diagnostics,
        )
        log_event("job_invalid_fit", job_id=job_id, seconds=round(seconds, 2), reason=str(exc))
        return {
            "job_id": job_id,
            "execution_status": "completed",
            "scientific_status": "invalid_fit",
            "reason": str(exc),
        }
    except Exception as exc:
        seconds = time.time() - started
        mark_job(
            job_id,
            "error",
            "not_evaluated",
            context,
            seconds=seconds,
            error_type=type(exc).__name__,
            reason=str(exc),
        )
        log_event("job_error", job_id=job_id, error_type=type(exc).__name__, reason=str(exc))
        raise


def ledger_table() -> pd.DataFrame:
    rows = []
    for job_id, entry in JOB_LEDGER.items():
        rows.append({"job_id": job_id, **entry})
    return pd.DataFrame(rows)


RUN_FINGERPRINT = {
    "engine": CFG["engine_version"],
    "config": stable_hash(CFG),
    "environment": stable_hash(PACKAGE_VERSIONS),
    "notebook": NOTEBOOK_SHA256,
}
log_event("session_start", mode=MODE, report_root=str(REPORT_ROOT), engine=CFG["engine_version"])

