@cached("chronology_contrast_v7_14_5")
def _chronology_contrast(
    train: pd.DataFrame,
    test: pd.DataFrame,
    columns: Sequence[str],
    seed: int,
) -> dict[str, Any]:
    return c2st_profile(
        train,
        test,
        columns,
        seed=seed,
        row_cap=CFG["row_cap_metrics"],
        n_splits=max(2, min(3, CFG["c2st_splits"])),
        n_permutations=2,
    )


def chronology_contrast(split: dict[str, Any], seed: int) -> dict[str, Any]:
    train = CANON_DF.iloc[split["train"]][FEATURE_SCOPES["protocol_value_v3"]].reset_index(drop=True)
    test = CANON_DF.iloc[split["test"]][FEATURE_SCOPES["protocol_value_v3"]].reset_index(drop=True)
    return _chronology_contrast(
        train,
        test,
        FEATURE_SCOPES["protocol_value_v3"],
        seed,
        _key={
            "dataset": RUN_FINGERPRINT["dataset"],
            "split": split_signature(split),
            "scope": stable_hash(FEATURE_SCOPES["protocol_value_v3"]),
            "seed": int(seed),
        },
    )


def apply_p0_licences(utility: pd.DataFrame, spec: GeneratorSpec) -> pd.DataFrame:
    """Apply capability-specific P0 licences without hiding unsupported rows."""
    utility = utility.copy()
    estimand_columns = (
        "synthetic_loss", "reference_loss", "loss_ratio", "log_loss_ratio",
        "relative_excess_loss_vs_naive", "fraction_reference_advantage_lost",
        "noninferior",
    )
    utility["p0_licensed"] = False
    utility["p0_license_scope"] = "capability_specific"
    utility["p0_license_reason"] = ""
    for index, row in utility.iterrows():
        suite = str(row.get("suite", ""))
        capability = str(row.get("capability", ""))
        payload = P0_LICENSE_BY_CAPABILITY.get(capability, {}).get(suite, {})
        source_property_ok = bool(suite != "temporal" or spec.order_preserving)
        licensed = bool(payload.get("licensed", False) and source_property_ok)
        utility.at[index, "p0_licensed"] = licensed
        if licensed:
            utility.at[index, "p0_license_reason"] = "licensed"
            continue
        if suite == "temporal" and not spec.order_preserving:
            reason = "source_not_order_preserving"
        elif capability not in P0_LICENSE_BY_CAPABILITY:
            reason = "capability_not_qualified"
        elif not payload.get("eligible", False):
            reason = "capability_suite_not_estimable_in_p0"
        else:
            reason = "capability_p0_qualification_failed"
        utility.at[index, "p0_license_reason"] = reason
        if str(row.get("status", "")) == "ok":
            utility.at[index, "status"] = "p0_unlicensed"
            for column in estimand_columns:
                if column in utility:
                    utility.at[index, column] = np.nan
    return utility


def invalid_utility_rows(
    spec: GeneratorSpec,
    split: dict[str, Any],
    seed: int,
    evaluation_axis: str,
    status: str,
) -> pd.DataFrame:
    rows: list[dict[str, Any]] = []
    for card in VALID_TASK_MODELS:
        rows.append({
            "generator_id": spec.generator_id,
            "family": spec.family,
            "fold_id": str(split["fold_id"]),
            "reference_fold_id": str(split["fold_id"]),
            "evaluation_axis": evaluation_axis,
            "seed": int(seed),
            "card_id": card.card_id,
            "task_id": card.task.task_id,
            "model_id": card.model_id,
            "suite": card.task.suite,
            "task_type": card.task.task_type,
            "tier": card.task.tier,
            "task_family": card.task.family,
            "capability": card.task.capability,
            "target_family": card.task.target_family,
            "driver_tier": card.task.driver_tier,
            "signal_class": card.task.signal_class,
            "status": status,
            "scientific_status": status,
        })
    return pd.DataFrame(rows)



def persist_learned_health_diagnostics(
    spec: GeneratorSpec,
    split: dict[str, Any],
    seed: int,
    scientific_status: str,
    diagnostics: dict[str, Any],
    reason: str = "",
) -> None:
    """Persist identical run- and feature-level health evidence for every fit.

    This is deliberately status-neutral: valid and invalid learned fits are
    audited through the same columns and file schema.
    """
    if not spec.family.startswith("learned"):
        return

    payload = diagnostics or {}
    failed_predicates = payload.get("failed_predicates", [])
    if isinstance(failed_predicates, str):
        failed_predicates = [failed_predicates] if failed_predicates else []

    summary = {
        "generator_id": spec.generator_id,
        "family": spec.family,
        "fold_id": split["fold_id"],
        "seed": int(seed),
        "scientific_status": str(scientific_status),
        "invalid_fit_reason": str(reason) if scientific_status != "valid" else "",
        "failed_predicates": "|".join(map(str, failed_predicates)),
        "finite": payload.get("finite", np.nan),
        "variable_feature_fraction_among_real_variable": payload.get(
            "variable_feature_fraction_among_real_variable", np.nan
        ),
        "modeled_variable_feature_fraction": payload.get(
            "modeled_variable_feature_fraction", np.nan
        ),
        "unsupported_value_fraction": payload.get(
            "unsupported_value_fraction", np.nan
        ),
        "learned_scope_zero_rate_mae": payload.get(
            "learned_scope_zero_rate_mae", np.nan
        ),
        "learned_scope_zero_rate_p95": payload.get(
            "learned_scope_zero_rate_p95", np.nan
        ),
        "learned_scope_zero_rate_max": payload.get(
            "learned_scope_zero_rate_max", np.nan
        ),
        "model_health_json": json.dumps(
            payload.get("model_health", {}),
            sort_keys=True,
            default=str,
        ),
    }
    pd.DataFrame([summary]).to_csv(
        DIRS["tables"]
        / (
            f"learned_health_summary__{split['fold_id']}__"
            f"{spec.generator_id}__seed{seed}.csv"
        ),
        index=False,
    )

    feature_health = payload.get("feature_health", [])
    if feature_health:
        feature_frame = pd.DataFrame(feature_health)
        feature_frame.insert(0, "generator_id", spec.generator_id)
        feature_frame.insert(1, "fold_id", split["fold_id"])
        feature_frame.insert(2, "seed", int(seed))
        feature_frame.insert(3, "scientific_status", str(scientific_status))
        feature_frame.to_csv(
            DIRS["tables"]
            / (
                f"learned_feature_health__{split['fold_id']}__"
                f"{spec.generator_id}__seed{seed}.csv"
            ),
            index=False,
        )


def write_invalid_benchmark_artifacts(
    spec: GeneratorSpec,
    split: dict[str, Any],
    seed: int,
    reason: str,
    diagnostics: dict[str, Any] | None = None,
) -> dict[str, Any]:
    metrics = {
        "generator_id": spec.generator_id,
        "family": spec.family,
        "fold_id": split["fold_id"],
        "seed": int(seed),
        "order_preserving": bool(spec.order_preserving),
        "release_eligible": bool(spec.release_eligible),
        "scientific_status": "invalid_fit",
        "invalid_fit_reason": reason,
        "invalid_fit_diagnostics": diagnostics or {},
    }
    result_path = DIRS["metrics"] / f"metrics__{split['fold_id']}__{spec.generator_id}__seed{seed}.json"
    write_json(result_path, metrics)

    diagnostics_payload = diagnostics or {}
    persist_learned_health_diagnostics(
        spec=spec,
        split=split,
        seed=seed,
        scientific_status="invalid_fit",
        diagnostics=diagnostics_payload,
        reason=reason,
    )

    utility_path = DIRS["utility"] / f"utility__{split['fold_id']}__{spec.generator_id}__seed{seed}.csv"
    invalid_utility_rows(spec, split, seed, "future", "invalid_generator_fit").to_csv(
        utility_path, index=False
    )
    return {"scientific_status": "invalid_fit", "result_path": str(result_path)}


def benchmark_job(spec: GeneratorSpec, split: dict[str, Any], seed: int) -> dict[str, Any]:
    stage_context = {
        "generator_id": spec.generator_id,
        "fold_id": split["fold_id"],
        "seed": int(seed),
    }
    log_event("benchmark_stage", stage="start", **stage_context)
    generator_columns = FEATURE_SCOPES["generator_v2"]
    headline_columns = FEATURE_SCOPES["protocol_value_v3"]
    all_value_columns = FEATURE_SCOPES["all_value_v3"]
    observability_columns = FEATURE_SCOPES["observability_v1"]
    mask_only_columns = FEATURE_SCOPES.get("mask_only_v1", observability_columns)
    train = CANON_DF.iloc[split["train"]][generator_columns].reset_index(drop=True)
    test = CANON_DF.iloc[split["test"]][generator_columns].reset_index(drop=True)
    n_future = int(CFG["generation_rows"])

    started = time.time()
    try:
        synthetic = generate_frame(spec, train, n_future, seed)
        generation_seconds = time.time() - started
        output_health = generator_output_health(spec, train, synthetic)
    except ScientificInvalidFit as exc:
        log_event(
            "benchmark_stage", stage="invalid_fit_during_generation",
            reason=str(exc), **stage_context,
        )
        return write_invalid_benchmark_artifacts(
            spec, split, seed, str(exc), getattr(exc, "diagnostics", {})
        )
    log_event(
        "benchmark_stage", stage="generated",
        seconds=round(generation_seconds, 3), **stage_context,
    )

    persist_learned_health_diagnostics(
        spec=spec,
        split=split,
        seed=seed,
        scientific_status="valid",
        diagnostics=output_health,
    )

    if RUN_PROFILE == "learned_health":
        health_result_path = (
            DIRS["metrics"]
            / f"health_only__{split['fold_id']}__{spec.generator_id}__seed{seed}.json"
        )
        write_json(
            health_result_path,
            {
                "generator_id": spec.generator_id,
                "family": spec.family,
                "fold_id": split["fold_id"],
                "seed": int(seed),
                "scientific_status": "valid",
                "run_profile": RUN_PROFILE,
                "generation_rows": int(len(synthetic)),
                "generation_seconds": float(generation_seconds),
                "output_health": output_health,
            },
        )
        log_event(
            "benchmark_stage",
            stage="health_only_written",
            scientific_status="valid",
            **stage_context,
        )
        return {
            "scientific_status": "valid",
            "result_path": str(health_result_path),
            "health_only": True,
        }

    metrics: dict[str, Any] = {
        "generator_id": spec.generator_id,
        "family": spec.family,
        "fold_id": split["fold_id"],
        "seed": int(seed),
        "order_preserving": bool(spec.order_preserving),
        "release_eligible": bool(spec.release_eligible),
        "generation_rows": int(len(synthetic)),
        "generation_seconds": float(generation_seconds),
        "output_health": output_health,
    }

    future_real = test[headline_columns].reset_index(drop=True)
    future_syn = synthetic[headline_columns].reset_index(drop=True)
    future_all_real = test[all_value_columns].reset_index(drop=True)
    future_all_syn = synthetic[all_value_columns].reset_index(drop=True)
    metrics.update({
        f"future_{key}": value
        for key, value in marginal_profile(future_real, future_syn, headline_columns).items()
    })
    metrics.update({
        f"future_{key}": value
        for key, value in temporal_profile(
            future_real, future_syn, headline_columns, lags=CFG["acf_lags"]
        ).items()
    })
    metrics.update({
        f"future_{key}": value
        for key, value in coupling_profile_from_pairs(
            future_all_real, future_all_syn, COUPLING_PAIRS, lag=0
        ).items()
    })
    metrics.update({
        f"future_{key}": value
        for key, value in c2st_profile(
            future_real,
            future_syn,
            headline_columns,
            seed=seed,
            row_cap=CFG["row_cap_metrics"],
        ).items()
    })
    # Secondary all-modal scope is intentionally separate from the protocol
    # headline estimand so high-volume telemetry cannot dominate by column count.
    metrics.update({
        f"future_all_modal_{key}": value
        for key, value in marginal_profile(
            future_all_real, future_all_syn, all_value_columns
        ).items()
    })
    metrics.update({
        f"future_all_modal_{key}": value
        for key, value in c2st_profile(
            future_all_real,
            future_all_syn,
            all_value_columns,
            seed=seed + 31_337,
            row_cap=CFG["row_cap_metrics"],
        ).items()
    })
    if observability_columns:
        metrics.update({
            f"future_observability_{key}": value
            for key, value in marginal_profile(
                test[observability_columns].reset_index(drop=True),
                synthetic[observability_columns].reset_index(drop=True),
                observability_columns,
            ).items()
        })
        metrics.update({
            f"future_observability_{key}": value
            for key, value in temporal_profile(
                test[observability_columns].reset_index(drop=True),
                synthetic[observability_columns].reset_index(drop=True),
                observability_columns,
                lags=CFG["acf_lags"],
            ).items()
        })
        metrics.update({
            f"future_mask_only_{key}": value
            for key, value in c2st_profile(
                test[mask_only_columns].reset_index(drop=True),
                synthetic[mask_only_columns].reset_index(drop=True),
                mask_only_columns,
                seed=seed + 47_117,
                row_cap=CFG["row_cap_metrics"],
            ).items()
        })
    metrics.update({
        f"chronology_train_future_{key}": value
        for key, value in chronology_contrast(split, seed).items()
    })
    log_event("benchmark_stage", stage="future_metrics_complete", **stage_context)

    # Same-period arm. The generator is fitted on inner_fit and evaluated against
    # disjoint inner_calib. Synthetic task-training size remains fixed and matched
    # to TRTR; only fidelity sampling is limited by available calibration rows.
    inner_synthetic: pd.DataFrame | None = None
    inner_fit: pd.DataFrame | None = None
    inner_calib: pd.DataFrame | None = None
    if split["fold_id"] == "primary" and len(split.get("inner_calib", [])) >= 1000:
        inner_fit = CANON_DF.iloc[split["inner_fit"]][generator_columns].reset_index(drop=True)
        inner_calib = CANON_DF.iloc[split["inner_calib"]][generator_columns].reset_index(drop=True)
        try:
            inner_synthetic = generate_frame(
                spec, inner_fit, int(CFG["same_period_generation_rows"]), seed + 100_000
            )
            generator_output_health(spec, inner_fit, inner_synthetic)
        except ScientificInvalidFit as exc:
            return write_invalid_benchmark_artifacts(
                spec,
                split,
                seed,
                f"same-period fit failed: {exc}",
                getattr(exc, "diagnostics", {}),
            )
        n_fidelity = min(len(inner_calib), len(inner_synthetic))
        real_calib = inner_calib.iloc[:n_fidelity][headline_columns].reset_index(drop=True)
        syn_calib = inner_synthetic.iloc[:n_fidelity][headline_columns].reset_index(drop=True)
        real_calib_all = inner_calib.iloc[:n_fidelity][all_value_columns].reset_index(drop=True)
        syn_calib_all = inner_synthetic.iloc[:n_fidelity][all_value_columns].reset_index(drop=True)
        metrics["same_period_real_rows"] = int(n_fidelity)
        metrics["same_period_synthetic_rows"] = int(len(inner_synthetic))
        metrics.update({
            f"same_period_{key}": value
            for key, value in marginal_profile(real_calib, syn_calib, headline_columns).items()
        })
        metrics.update({
            f"same_period_{key}": value
            for key, value in temporal_profile(
                real_calib, syn_calib, headline_columns, lags=CFG["acf_lags"]
            ).items()
        })
        metrics.update({
            f"same_period_{key}": value
            for key, value in coupling_profile_from_pairs(
                real_calib_all, syn_calib_all, COUPLING_PAIRS, lag=0
            ).items()
        })
        metrics.update({
            f"same_period_{key}": value
            for key, value in c2st_profile(
                real_calib,
                syn_calib,
                headline_columns,
                seed=seed + 100_000,
                row_cap=min(CFG["row_cap_metrics"], 60000),
            ).items()
        })
        metrics.update({
            f"same_period_all_modal_{key}": value
            for key, value in marginal_profile(
                real_calib_all, syn_calib_all, all_value_columns
            ).items()
        })
        metrics.update({
            f"same_period_all_modal_{key}": value
            for key, value in c2st_profile(
                real_calib_all,
                syn_calib_all,
                all_value_columns,
                seed=seed + 131_337,
                row_cap=min(CFG["row_cap_metrics"], 60000),
            ).items()
        })
        if observability_columns:
            metrics.update({
                f"same_period_observability_{key}": value
                for key, value in marginal_profile(
                    inner_calib.iloc[:n_fidelity][observability_columns].reset_index(drop=True),
                    inner_synthetic.iloc[:n_fidelity][observability_columns].reset_index(drop=True),
                    observability_columns,
                ).items()
            })
            metrics.update({
                f"same_period_observability_{key}": value
                for key, value in temporal_profile(
                    inner_calib.iloc[:n_fidelity][observability_columns].reset_index(drop=True),
                    inner_synthetic.iloc[:n_fidelity][observability_columns].reset_index(drop=True),
                    observability_columns,
                    lags=CFG["acf_lags"],
                ).items()
            })
            metrics.update({
                f"same_period_mask_only_{key}": value
                for key, value in c2st_profile(
                    inner_calib.iloc[:n_fidelity][mask_only_columns].reset_index(drop=True),
                    inner_synthetic.iloc[:n_fidelity][mask_only_columns].reset_index(drop=True),
                    mask_only_columns,
                    seed=seed + 147_117,
                    row_cap=min(CFG["row_cap_metrics"], 60000),
                ).items()
            })
    log_event("benchmark_stage", stage="same_period_complete", **stage_context)

    # Fit validity is distinct from generator quality. A completed, support-valid
    # learned model may be highly separable or have poor utility; those are valid
    # negative quality results rather than evidence of computational collapse.
    scientific_status = "valid"
    metrics["scientific_status"] = scientific_status

    utility_frames: list[pd.DataFrame] = []
    if scientific_status == "valid":
        future_utility = apply_p0_licences(evaluate_utility(
            synthetic,
            spec,
            split,
            seed,
            evaluation_axis="future",
            reported_fold_id=split["fold_id"],
        ), spec)
        future_utility["scientific_status"] = scientific_status
        utility_frames.append(future_utility)
        metrics.update(summarize_utility_rows(
            future_utility, "contemporaneous", prefix="future_utility"
        ))
        metrics.update(summarize_utility_rows(
            future_utility, "temporal", prefix="future_utility"
        ))

        if inner_synthetic is not None:
            inner_split = {
                "fold_id": f"{split['fold_id']}_inner_same_period",
                "train": np.asarray(split["inner_fit"], dtype=np.int64),
                "val": np.asarray([], dtype=np.int64),
                "test": np.asarray(split["inner_calib"], dtype=np.int64),
                "inner_fit": np.asarray([], dtype=np.int64),
                "inner_calib": np.asarray([], dtype=np.int64),
            }
            same_period_utility = apply_p0_licences(evaluate_utility(
                inner_synthetic,
                spec,
                inner_split,
                seed + 100_000,
                evaluation_axis="same_period",
                reported_fold_id=split["fold_id"],
            ), spec)
            same_period_utility["scientific_status"] = scientific_status
            utility_frames.append(same_period_utility)
            metrics.update(summarize_utility_rows(
                same_period_utility, "contemporaneous", prefix="same_period_utility"
            ))
            metrics.update(summarize_utility_rows(
                same_period_utility, "temporal", prefix="same_period_utility"
            ))
    else:
        utility_frames.append(invalid_utility_rows(
            spec, split, seed, "future", scientific_status
        ))
        if inner_synthetic is not None:
            utility_frames.append(invalid_utility_rows(
                spec, split, seed, "same_period", scientific_status
            ))

    utility = pd.concat(utility_frames, ignore_index=True)
    utility_path = DIRS["utility"] / f"utility__{split['fold_id']}__{spec.generator_id}__seed{seed}.csv"
    utility.to_csv(utility_path, index=False)
    log_event("benchmark_stage", stage="utility_complete", **stage_context)

    # Calibrated disclosure diagnostics use only disjoint same-period data.
    # Future overlap is retained separately as descriptive evidence and is never
    # interpreted as a membership attack or same-period natural-collision floor.
    if inner_synthetic is not None and inner_fit is not None and inner_calib is not None:
        calibrated_disclosure = disclosure_profile(
            inner_fit, inner_calib, inner_synthetic, spec, seed + 200_000
        )
        metrics.update({
            f"same_period_disclosure_{key}": value
            for key, value in calibrated_disclosure.items()
        })
    future_row_overlap = verbatim_row_profile(train, synthetic, PRIVACY_COLS, seed=seed)
    future_trajectory_overlap = trajectory_overlap_profile(
        train,
        synthetic,
        TRAJECTORY_COLS,
        window=min(60, CFG["max_window_span"]),
        seed=seed,
    )
    future_activity_overlap = activity_trajectory_overlap_profile(
        train,
        synthetic,
        TRAJECTORY_COLS,
        window=min(60, CFG["max_window_span"]),
        seed=seed,
    )
    for payload in (future_row_overlap, future_trajectory_overlap, future_activity_overlap):
        metrics.update({f"future_descriptive_{key}": value for key, value in payload.items()})
    log_event("benchmark_stage", stage="disclosure_complete", **stage_context)

    result_path = DIRS["metrics"] / f"metrics__{split['fold_id']}__{spec.generator_id}__seed{seed}.json"
    write_json(result_path, metrics)
    if CFG["save_synthetic_frames"]:
        save_frame(
            synthetic,
            DIRS["models"] / f"synthetic__{split['fold_id']}__{spec.generator_id}__seed{seed}.parquet",
        )
    del synthetic
    if inner_synthetic is not None:
        del inner_synthetic
    gc.collect()
    log_event(
        "benchmark_stage", stage="written",
        scientific_status=scientific_status, **stage_context,
    )
    return {"scientific_status": scientific_status, "result_path": str(result_path)}


