    }


BENCHMARK_SEEDS = [SEED0] if MODE == "smoke" else list(SEEDS)


def build_plan() -> list[tuple[int, GeneratorSpec, dict[str, Any], int]]:
    plan: list[tuple[int, GeneratorSpec, dict[str, Any], int]] = []
    selected_specs = list(GENERATOR_SPECS)
    if RUN_PROFILE == "learned_health":
        selected_specs = [
            spec for spec in GENERATOR_SPECS
            if spec.generator_id in {
                "learned_gmm_overlay",
                "learned_latent_var_overlay",
            }
        ]
        if len(selected_specs) != 2:
            raise RuntimeError(
                "learned_health profile requires both learned_gmm_overlay and "
                "learned_latent_var_overlay in the generator registry"
            )
    priority_order = {
        "real_resample": 0,
        "real_block": 1,
        "hurdle_shared_stitch": 2,
        "learned_latent_var_overlay": 3,
        "learned_gmm_overlay": 4,
        "hurdle_independent_stitch": 5,
        "hurdle_iid": 6,
        "independent_marginal": 7,
        "column_shuffle": 8,
        "hurdle_pca_var1": 20,
        "hurdle_pca_gru": 21,
        "state_markov_bootstrap": 22,
    }
    for spec in selected_specs:
        for seed in BENCHMARK_SEEDS:
            plan.append((priority_order.get(spec.generator_id, 50), spec, PRIMARY_SPLIT, seed))
    if MODE == "real" and RUN_PROFILE == "full":
        rolling_ids = {
            "real_resample", "real_block", "hurdle_shared_stitch",
            "learned_latent_var_overlay", "learned_gmm_overlay",
        }
        for fold in ROLLING_FOLDS:
            for spec in selected_specs:
                if spec.generator_id in rolling_ids:
                    plan.append((20 + priority_order.get(spec.generator_id, 50), spec, fold, SEED0))
    return sorted(
        plan,
        key=lambda row: (row[0], row[2]["fold_id"], row[1].generator_id, row[3]),
    )


